var accountClassificationId = Get<Guid>("AccountClassification");
var workingDaysToAdd = 0;
if (accountClassificationId == PgrConstants.AccountClassification.A)
{
	workingDaysToAdd = 3;
}
else if (accountClassificationId == PgrConstants.AccountClassification.B ||
			         accountClassificationId == PgrConstants.AccountClassification.C)
{
	workingDaysToAdd = 5;
}

var accountId = Get<Guid>("Account");
var workingDayHelper = new PgrAccountWorkingDayHelper(context.UserConnection);
var currentDate = DateTime.Now;
var endDate = workingDayHelper.AddWorkingDays(currentDate, workingDaysToAdd, accountId);

Set("TaskDueDate", endDate);

return true;
